//fake lighting using cross product of various pixels from A
void mainImage(out vec4 O, vec2 u) {

    vec2 R = iResolution.xy,
        uv = u/R.xy;

    float Rxy = length(R.xy);

    O *= 0.;

    float[] gk1s = float[](
        0.003765, 0.015019, 0.023792, 0.015019, 0.003765,
        0.015019, 0.059912, 0.094907, 0.059912, 0.015019,
        0.023792, 0.094907, 0.150342, 0.094907, 0.023792,
        0.015019, 0.059912, 0.094907, 0.059912, 0.015019,
        0.003765, 0.015019, 0.023792, 0.015019, 0.003765
    );


    vec4 total_color = vec4(0.0,0.0,0.0,0.0);
    vec2 tex = 1./R.xy;
    float one_pixel = 5.5/Rxy;
    float color = 0.0;
    for (int i=0; i<5; i++) {
        for (int j=0; j<5; j++) {                             

            vec4 x2 =  texture(iChannel0,uv+vec2( 0.0,  one_pixel) + vec2( i-2,j-2 ) * tex);
            vec4 x3 =  texture(iChannel0,uv+vec2( one_pixel, 0.) + vec2( i-2,j-2 ) * tex);
            vec4 x4 =  texture(iChannel0,uv+vec2( 0.0, -one_pixel) + vec2( i-2,j-2 ) * tex);

            float a = x3.x*x2.y - x3.y*x2.x;
            float c = x3.x*x2.w - x3.w*x2.x;
            float e = x3.y*x2.w - x3.w*x2.y;

            color +=  gk1s[i*5 + j] * 
                ( (a*x4.w - c*x4.y + e*x4.x) );
        }
    }

    float  xxx =  1.-color*Rxy*Rxy/5000.;
    vec4 actual_pixel = texture(iChannel0, uv);

    float zzz = sin( 32.*actual_pixel.z  + iTime);

    vec3 cc = xxx*xxx*vec3(0,.25,.8) + zzz*zzz*vec3(.3);

    O = vec4( cc, 0.);

    O*=O;
    O*=O;


}

